import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This algorithm is a simple random search with uniform sampling within the search bounds.
# Search state: The algorithm maintains the current best solution.
# Candidate generation: New candidates are generated by uniformly sampling the search space.
# Selection and replacement: The best candidate found so far is kept as the current best solution.
# Adaptation: There is no adaptation mechanism in this algorithm.
# Exploration mechanisms: The algorithm explores the search space by uniformly sampling new candidates.
# Exploitation mechanisms: The algorithm does not have any explicit exploitation mechanisms.
# Boundary handling: The algorithm simply rejects any candidates that fall outside the search bounds.
# Budget strategy: The algorithm uses the full evaluation budget provided.
# Closest known influences: This algorithm is a basic random search algorithm, which is a common baseline for black-box optimization problems.
# Novelty or unusual aspects: This algorithm does not have any novel or unusual aspects.
# Failure modes: The algorithm may struggle in high-dimensional problems or problems with complex, non-convex landscapes, as it relies solely on random sampling without any additional mechanisms to guide the search.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Read the search bounds from the function
        if hasattr(func, "lower") and hasattr(func, "upper"):
            lb, ub = func.lower, func.upper
        elif hasattr(func, "bounds") and hasattr(func.bounds, "lb") and hasattr(func.bounds, "ub"):
            lb, ub = func.bounds.lb, func.bounds.ub
        else:
            raise ValueError("Could not determine search bounds from the given function")

        # Initialize the best solution
        best_x = np.random.uniform(lb, ub, size=self.dim)
        best_y = func(best_x)

        # Perform the random search
        for _ in range(self.budget - 1):
            x = np.random.uniform(lb, ub, size=self.dim)
            y = func(x)
            if y < best_y:
                best_x, best_y = x, y

        return best_x, best_y
